def probe(t):
    x = min(max(float(t), 0.0), 1.0) * 50.0
    i = int(x)
    if i >= 50:
        return list(W[50])
    f = x - i
    if f < 1e-9:
        return list(W[i])
    if f > 1 - 1e-9:
        return list(W[i + 1])
    a, b = W[i], W[i + 1]
    return [(1 - f) * u + f * v for u, v in zip(a, b)]


if __name__ == '__main__':
    fptr = open(os.environ['OUTPUT_PATH'], 'w')
    t = float(input().strip())
    result = probe(t)
    fptr.write('\n'.join(map(str, result)))
    fptr.write('\n')
    fptr.close()
